import org.springframework.core.annotation.AnnotatedElementUtils;
import org.springframework.core.annotation.AnnotationUtils;
import java.lang.reflect.Method;
import java.lang.reflect.Parameter;
import java.lang.reflect.Type;

private Type determineInferredType() {
    if (this.method == null) {
        return null;
    }

    Type genericParameterType = null;
    boolean ambiguous = false;

    for (Parameter parameter : this.method.getParameters()) {
        MethodParameter methodParameter = MethodParameter.forParameter(parameter);

        boolean isHeader = AnnotatedElementUtils.hasAnnotation(methodParameter.getParameter(), Header.class);
        boolean isPayload = AnnotatedElementUtils.hasAnnotation(methodParameter.getParameter(), Payload.class);

        if (isHeader && isPayload) {
            if (MessagingMessageListenerAdapter.this.logger.isWarnEnabled()) {
                MessagingMessageListenerAdapter.this.logger.warn(this.method.getName()
                        + ": Cannot annotate a parameter with both @Header and @Payload; "
                        + "ignored for payload conversion");
            }
        }

        if (isEligibleParameter(methodParameter) && (!isHeader || isPayload)) {
            Type parameterType = extractParameterType(methodParameter);
            if (parameterType != null) {
                if (genericParameterType == null) {
                    genericParameterType = parameterType;
                } else {
                    ambiguous = true;
                    if (MessagingMessageListenerAdapter.this.logger.isDebugEnabled()) {
                        MessagingMessageListenerAdapter.this.logger.debug("Ambiguous parameters for target payload for method " + this.method
                                + "; no inferred type header added");
                    }
                    break; // Break out of loop if ambiguity is found
                }
            }
        }
    }

    if (ambiguous) {
        return null;
    }

    return genericParameterType;
}

private Type extractParameterType(MethodParameter methodParameter) {
    Type parameterType = methodParameter.getGenericParameterType();
    if (parameterType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) parameterType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
        if (actualTypeArguments.length > 0) {
            return actualTypeArguments[0];
        }
    }
    return null;
}

